let runId=0;

const $=s=>document.querySelector(s);const fmt=n=>'$'+Math.round(n).toLocaleString('en-CA');
const pill=(t)=>`<span class="pill ${t=='High'?'hi':t=='Medium'?'md':'lo'}">${t}</span>`;
const bar=(p,c)=>`<div class="bar"><i style="width:${p}%;${c?'background:'+c:''}"></i></div>`;
const tbl=(h,rows)=>`<table><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table>`;
const kpis=a=>`<div class="kpis">${a.map(([l,v,c])=>`<div class="kpi"><small>${l}</small><b style="color:${c||'inherit'}">${v}</b></div>`).join('')}</div>`;
function hbars(items,max,color){return `<svg width="100%" viewBox="0 0 420 ${items.length*30+6}">${items.map(([l,v],i)=>`<text x="0" y="${i*30+18}" font-size="12" fill="#475467">${l}</text><rect x="150" y="${i*30+6}" width="${v/max*230}" height="16" rx="3" fill="${color||'#4f9cff'}"/><text x="${156+v/max*230}" y="${i*30+18}" font-size="11" fill="#1b2333">${typeof v=='number'&&v>999?fmt(v):v}</text>`).join('')}</svg>`}
function line(vals,color){const mx=Math.max(...vals),w=420,h=120;const pts=vals.map((v,i)=>`${i*(w/(vals.length-1))},${h-v/mx*(h-10)}`).join(' ');return `<svg width="100%" viewBox="-4 -4 ${w+8} ${h+8}"><polyline points="${pts}" fill="none" stroke="${color||'#0f6cbd'}" stroke-width="3"/>${vals.map((v,i)=>`<circle cx="${i*(w/(vals.length-1))}" cy="${h-v/mx*(h-10)}" r="3.5" fill="${color||'#0f6cbd'}"/>`).join('')}</svg>`}
function donut(p,color,label){const r=40,c=2*Math.PI*r;return `<svg width="120" height="120" viewBox="0 0 100 100"><circle cx="50" cy="50" r="${r}" fill="none" stroke="#e8edf5" stroke-width="12"/><circle cx="50" cy="50" r="${r}" fill="none" stroke="${color}" stroke-width="12" stroke-dasharray="${c*p/100} ${c}" transform="rotate(-90 50 50)"/><text x="50" y="50" text-anchor="middle" font-size="18" font-weight="700">${p}</text><text x="50" y="65" text-anchor="middle" font-size="8" fill="#667085">${label||''}</text></svg>`}
function toast(m){const t=$('#toast');t.innerHTML='✅ '+m;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),3800)}
const hitl=(txt,btn,msg)=>`<div class="hitl"><span>🧑‍💼 <b>Human-in-the-loop:</b> ${txt}</span><button class="btn sec" onclick="toast('Sent back to agent for revision')">Edit</button><button class="btn ok" onclick="this.disabled=true;this.textContent='Approved ✓';toast(${JSON.stringify(msg).replace(/"/g,'&quot;')})">${btn}</button></div>`;

