function xrender(){$('#xbrief').innerHTML=xbriefHtml()}
function xsel(i){XS.i=i;xrender()}
function xtog(k){const o=XP[XS.i].on;const j=o.indexOf(k);j<0?o.push(k):o.splice(j,1);xrender()}
async function run(d,pi){const my=++runId;const out=$('#out');$('#run').disabled=true;
if(d.chat==2){out.innerHTML=`<div class="card"><h4>Website chat — northbridge.ca</h4><div class="chat" id="chat"></div><div id="fin"></div></div>`;const c=$('#chat');
for(const [w,t] of d.script){await sleep((w=='bot'?1000:800)*SPEED);if(my!=runId)return;c.insertAdjacentHTML('beforeend',`<div class="msg ${w=='bot'?'bot':'usr'}">${t=='CFG'?'Here\'s your configured bundle:<br>'+d.cfg():t}</div>`);c.scrollTop=c.scrollHeight}
$('#fin').innerHTML=kpis([['Lead qualified','Yes · score 87'],['Time to sign-up','6 min'],['Annual contract value',fmt((35*29.7+10*40.5)*12),'#2e9e5b']])+hitl('Review auto-provisioned order before first invoice.','Approve order','Order confirmed; welcome call booked with Northbridge SMB team');$('#run').disabled=false;return}
out.innerHTML=`<div class="card"><h4>Agent activity</h4><div class="log" id="log"></div></div><div id="res"></div>`;const log=$('#log');
for(const s0 of d.steps){if(my!=runId)return;const s=Array.isArray(s0)?(s0[0]=='Executive Copilot'?`<b style="color:#9cc7ff">Executive Copilot</b> ${s0[1]}`:`<span class="sub">↳ calling sub-agent</span> <b>${s0[0]}</b> — ${s0[1]}`):s0;
log.insertAdjacentHTML('beforeend',`<div><span class="sp"></span>${s}</div>`);await sleep((d.exec?450:650)*SPEED);if(my!=runId)return;log.lastElementChild.innerHTML='<span class="d">✓</span> '+s}
log.insertAdjacentHTML('beforeend',`<div class="d">● Agent complete — results ready for review</div>`);
let html;if(d.exec)html=`<div class="card">${execRender()}</div>`;
else if(d.chat==1){const [a,c]=d.answers[pi]||d.answers[0];html=`<div class="card"><h4>Q: ${d.prompts[pi]||d.prompts[0]}</h4><div class="msg bot" style="max-width:100%">${a}</div><h4 style="margin-top:12px">Sources</h4>${c.map((x,i)=>`<div class="cite">[${i+1}] ${x}</div>`).join('')}${hitl('Save this answer to the Northbridge licensing knowledge base?','Approve & publish','Answer published to seller knowledge base')}</div>`}
else html=`<div class="card">${d.render()}${d.approve?hitl(...d.approve):''}</div>`;
$('#res').innerHTML=html;$('#run').disabled=false}
